/// Silent compaction hooks: a child has no TUI — the handle's compaction
/// receipt ([SubagentManager.recordCompaction]) is the observability
/// surface (issue #439).
final class _SilentCompactionHooks extends AutoCompactorHooks {
  _SilentCompactionHooks();

  /// Whether the engine ATTEMPTED any pass (issue #1924 review round 1):
  /// a gate-declined no-op (`shouldCompact` re-check declines — e.g. the
  /// resume probe where only `+ incomingTokens` crossed the trigger while
  /// the transcript sits under it) fires NO pass and NO attempt — the
  /// caller must never read that healthy no-op as a failed pass.
  bool attempted = false;

  @override
  void onPass(AutoCompactorPass pass) {
    attempted = true;
  }

  @override
  void onRetry(int attempt, int maxAttempts, Duration backoff, Object error) {}

  @override
  void onDone(int passes, int tokens) {
    if (passes > 0) attempted = true;
  }

  @override
  void onBothRolesFailed(Object lastError) {}
}

/// Whether [onDelta] streamed dimmed summary bytes on the log face
/// (gh-1433 E4): the next compaction-facing line closes the stream
/// line first, so the report never glues onto the live summary.
bool _deltaStreamed = false;

/// Closes the E4 live-summary stream line (one newline on the primary
/// channel) before the next compaction-facing output lands.
void _closeDeltaStreamLine() {
  if (!_deltaStreamed) return;
  _deltaStreamed = false;
  cli.io.write('\n');
}

@override
void onDelta(String delta) {
  // gh-1636: the summary being written is internal checkpoint text —
  // echoing every delta onto the headless log buries the actual reply
  // the same way the full report block did. Hidden by default; the
  // gh-1430 E3 tier-2 `… reasoning Ns` line (armed around the whole
